#!/usr/bin/env node
/**
 * Build the GO TOP SEO Bridge WordPress plugin zip from wordpress-plugin/gotop-seo-bridge.
 *
 *   node scripts/build-wordpress-plugin.mjs                 # refresh lib/site-fix/plugin-zip.generated.ts
 *   node scripts/build-wordpress-plugin.mjs --out plugin.zip  # ...and also write the zip file
 *   node scripts/build-wordpress-plugin.mjs --check          # exit 1 when the generated file is stale
 *
 * The app serves the zip from the generated module (GET /api/site-health/plugin-zip), so the
 * download always matches the PHP in the repo; a QA guard runs --check. The zip is deterministic:
 * entries sorted, stored (no compression, so no zlib-version drift), fixed timestamps. Its folder
 * is "gotop-seo-bridge/", which WordPress's "Upload plugin" expects.
 * The repo-only README.md is left out; readme.txt is what WordPress shows.
 */
import { createHash } from 'node:crypto'
import { readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs'
import { join, relative, sep } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = join(fileURLToPath(import.meta.url), '..', '..')
const SRC = join(ROOT, 'wordpress-plugin', 'gotop-seo-bridge')
const GENERATED = join(ROOT, 'lib', 'site-fix', 'plugin-zip.generated.ts')
const FOLDER = 'gotop-seo-bridge'

function listFiles(dir) {
  const out = []
  for (const name of readdirSync(dir).sort()) {
    const full = join(dir, name)
    if (statSync(full).isDirectory()) out.push(...listFiles(full))
    else if (name !== 'README.md' && !name.startsWith('.')) out.push(full)
  }
  return out
}

const CRC_TABLE = (() => {
  const t = new Uint32Array(256)
  for (let n = 0; n < 256; n++) {
    let c = n
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1
    t[n] = c >>> 0
  }
  return t
})()
function crc32(buf) {
  let c = 0xffffffff
  for (const b of buf) c = CRC_TABLE[(c ^ b) & 0xff] ^ (c >>> 8)
  return (c ^ 0xffffffff) >>> 0
}

/** A stored (method 0) zip of [{ name, data }], byte-for-byte reproducible. */
export function storedZip(entries) {
  const DOS_TIME = 0, DOS_DATE = (0 << 9) | (1 << 5) | 1 // 1980-01-01 00:00
  const locals = [], centrals = []
  let offset = 0
  for (const { name, data } of entries) {
    const nameBuf = Buffer.from(name, 'utf8')
    const crc = crc32(data)
    const local = Buffer.alloc(30)
    local.writeUInt32LE(0x04034b50, 0); local.writeUInt16LE(20, 4); local.writeUInt16LE(0x0800, 6)
    local.writeUInt16LE(0, 8); local.writeUInt16LE(DOS_TIME, 10); local.writeUInt16LE(DOS_DATE, 12)
    local.writeUInt32LE(crc, 14); local.writeUInt32LE(data.length, 18); local.writeUInt32LE(data.length, 22)
    local.writeUInt16LE(nameBuf.length, 26); local.writeUInt16LE(0, 28)
    locals.push(local, nameBuf, data)
    const central = Buffer.alloc(46)
    central.writeUInt32LE(0x02014b50, 0); central.writeUInt16LE(20, 4); central.writeUInt16LE(20, 6)
    central.writeUInt16LE(0x0800, 8); central.writeUInt16LE(0, 10); central.writeUInt16LE(DOS_TIME, 12)
    central.writeUInt16LE(DOS_DATE, 14); central.writeUInt32LE(crc, 16); central.writeUInt32LE(data.length, 20)
    central.writeUInt32LE(data.length, 24); central.writeUInt16LE(nameBuf.length, 28)
    central.writeUInt32LE(0o100644 << 16 >>> 0, 38); central.writeUInt32LE(offset, 42)
    centrals.push(central, nameBuf)
    offset += 30 + nameBuf.length + data.length
  }
  const centralSize = centrals.reduce((n, b) => n + b.length, 0)
  const end = Buffer.alloc(22)
  end.writeUInt32LE(0x06054b50, 0); end.writeUInt16LE(entries.length, 8); end.writeUInt16LE(entries.length, 10)
  end.writeUInt32LE(centralSize, 12); end.writeUInt32LE(offset, 16)
  return Buffer.concat([...locals, ...centrals, end])
}

export function buildPlugin() {
  const main = readFileSync(join(SRC, 'gotop-seo-bridge.php'), 'utf8')
  const version = main.match(/^\s*\*\s*Version:\s*([0-9.]+)/m)?.[1]
  const constant = main.match(/define\('GOTOP_SEO_BRIDGE_VERSION', '([0-9.]+)'\)/)?.[1]
  if (!version || version !== constant) throw new Error('plugin header Version and GOTOP_SEO_BRIDGE_VERSION disagree')
  const entries = listFiles(SRC).map((full) => ({
    name: `${FOLDER}/${relative(SRC, full).split(sep).join('/')}`,
    data: readFileSync(full),
  }))
  const zip = storedZip(entries)
  return { version, zip, sha256: createHash('sha256').update(zip).digest('hex'), files: entries.map((e) => e.name) }
}

function generatedSource(built) {
  return `/**
 * GENERATED by scripts/build-wordpress-plugin.mjs from wordpress-plugin/gotop-seo-bridge.
 * Do not edit: change the PHP and run \`node scripts/build-wordpress-plugin.mjs\`.
 * A QA guard (lib/site-fix/__qa__/site-fix.qa.ts) fails when this is out of date.
 */
export const PLUGIN_VERSION = '${built.version}'
export const PLUGIN_ZIP_SHA256 = '${built.sha256}'
export const PLUGIN_ZIP_FILES: readonly string[] = ${JSON.stringify(built.files)}
export const PLUGIN_ZIP_BASE64 =
  '${built.zip.toString('base64')}'
`
}

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]
if (isMain) {
  const args = process.argv.slice(2)
  const built = buildPlugin()
  const source = generatedSource(built)
  if (args.includes('--check')) {
    let current = ''
    try { current = readFileSync(GENERATED, 'utf8') } catch { /* missing */ }
    if (current !== source) {
      console.log(`stale: ${relative(ROOT, GENERATED)} does not match the plugin sources — run node scripts/build-wordpress-plugin.mjs`)
      process.exit(1)
    }
    console.log(`up to date: GO TOP SEO Bridge ${built.version} (${built.zip.length} bytes, sha256 ${built.sha256.slice(0, 12)})`)
  } else {
    writeFileSync(GENERATED, source)
    const outIdx = args.indexOf('--out')
    if (outIdx >= 0 && args[outIdx + 1]) writeFileSync(args[outIdx + 1], built.zip)
    console.log(`built GO TOP SEO Bridge ${built.version}: ${built.files.length} files, ${built.zip.length} bytes${outIdx >= 0 ? ` -> ${args[outIdx + 1]}` : ''}`)
  }
}
